export const SIZE=8;
const GROUP={reserves:'A',loans:'A',allowance:'A',investment:'A',property:'A',equipment:'A',deposit:'A',outsideDeposit:'A',inventory:'A',repossessed:'A',deposits:'L',debt:'L',capital:'E',retained:'E',revaluation:'E'};
const sum=o=>Object.values(o).reduce((a,b)=>a+b,0);
export class Simulation{
 constructor(){this.day=1;this.settledDays=0;this.nextId=1;this.entities={};this.tiles=[];this.journal=[];this.status='active';this.pending=0;this.won=false;this.version=0;this.events=[];this.provisions={};this.seed();}
 entity(id,name,kind,x=null,y=null){const e={id,name,kind,x,y,accounts:{},level:0,upgrades:0,sponsor:null,closed:false};this.entities[id]=e;if(x!==null)this.tiles.push(e);return e;}
 balance(e){if(typeof e==='string')e=this.entities[e];const b={A:0,L:0,E:0};for(const [k,v]of Object.entries(e.accounts))b[GROUP[k]]+=v;return b;}
 amount(e,k){return(typeof e==='string'?this.entities[e]:e).accounts[k]||0;}
 post(label,entries){const checks={};for(const [id,account,dr,cr] of entries){if(!this.entities[id]||!GROUP[account]||!Number.isSafeInteger(dr)||!Number.isSafeInteger(cr)||dr<0||cr<0)throw Error('Invalid journal entry');checks[id]=(checks[id]||0)+dr-cr;}if(Object.values(checks).some(v=>v!==0))throw Error('Unbalanced transaction: '+label);
 const previous={};for(const [id,k]of entries)previous[id]??={...this.entities[id].accounts};
 for(const [id,k,dr,cr]of entries){const a=this.entities[id].accounts;a[k]=(a[k]||0)+(GROUP[k]==='A'?dr-cr:cr-dr);}
 try{this.auditReciprocal();}catch(error){for(const[id,a]of Object.entries(previous))this.entities[id].accounts=a;throw error;}
 this.journal.unshift({day:this.day,label,entries:entries.map(([id,k,dr,cr])=>({entity:this.entities[id].name,account:k,dr,cr}))});this.version++;
 }
 seed(){const b=this.entity('bank','Parent / Commercial Bank','parent',4,4);b.accounts={reserves:220,capital:220};this.entity('treasury','Outside treasury','external').accounts={reserves:5000,capital:5000};this.entity('market','Land & materials supplier','external').accounts={inventory:10000,capital:10000};this.entity('outside','District clearing bank','external');this.baseTotal=5220;this.buildUtility(3,4);this.originate(4,3,'bank');this.events=[];this.audit();}
 tile(x,y){return this.tiles.find(e=>e.x===x&&e.y===y);}
 district(e){return(e.x<4?0:1)+(e.y<4?0:2);}
 districtName(d){return['NORTH W','NORTH E','SOUTH W','SOUTH E'][d];}
 live(kind){return this.tiles.filter(e=>!e.closed&&(!kind||e.kind===kind));}
 get bank(){return this.entities.bank;}
 get reserves(){return this.amount('bank','reserves');}
 get broad(){return this.amount('bank','deposits')+this.amount('outside','deposits');}
 get risk(){return this.amount('bank','loans')+this.amount('bank','allowance')+this.amount('bank','investment')+this.amount('bank','repossessed');}
 get car(){return this.risk>0?100*this.balance('bank').E/this.risk:Infinity;}
 get income(){return Math.min(this.amount('treasury','reserves'),this.live('utility').reduce((n,e)=>n+12+e.upgrades*6,0));}
 get totals(){return this.tiles.reduce((b,e)=>{const x=this.balance(e);for(const k in b)b[k]+=x[k];return b;},{A:0,L:0,E:0});}
 get consolidated(){const t={...this.totals};const intra=this.amount('bank','loans')+this.amount('bank','investment');t.A-=intra+this.amount('bank','allowance');t.L-=this.amount('bank','loans');t.E-=this.amount('bank','investment')+this.amount('bank','allowance');return t;}
 get footprint(){return this.live().length-1;}
 get creditFrozen(){return this.car<8||this.status!=='active';}
 districts(day=this.day){return Array.from({length:4},(_,d)=>{const group=this.live().filter(e=>this.district(e)===d);const capacity=4+group.filter(e=>e.kind==='utility').reduce((n,e)=>n+4+e.upgrades*4,0)-(day%4===0?2:0);const demand=group.filter(e=>e.kind==='subsidiary').reduce((n,e)=>n+1+e.level*2,0);return{d,capacity,demand,stress:demand>capacity};});}
 get clearingPlan(){if(this.status==='liquidity'&&this.pendingPlan)return this.pendingPlan;const cross=this.live('subsidiary').filter(e=>e.sponsor&&this.district(e)!==this.district(this.entities[e.sponsor])).length;const outgoing=Math.ceil(this.amount('bank','deposits')*(.06+Math.min(.05,cross*.01))*(this.day%5===0?1.5:1));const incoming=Math.min(outgoing,this.amount('market','outsideDeposit'),this.live('utility').length*2);return{outgoing,incoming,net:outgoing-incoming};}
 get settlement(){return this.status==='liquidity'?this.pending:this.clearingPlan.net;}
 available(e){if(!e||e.closed||e.kind!=='subsidiary')return 0;const used=this.live('subsidiary').filter(c=>c.sponsor===e.id).length*100;return Math.max(0,this.balance(e).E-used);}
 canPlot(x,y){return Number.isInteger(x)&&Number.isInteger(y)&&x>=0&&y>=0&&x<SIZE&&y<SIZE&&!this.tile(x,y)&&this.live().some(e=>Math.abs(e.x-x)+Math.abs(e.y-y)===1);}
 require(ok,msg){if(!ok)throw Error(msg);}
 active(){this.require(this.status!=='meltdown','The bank has collapsed. Start a new simulation.');}
 buildUtility(x,y){this.active();this.require(this.status==='active','Resolve the liquidity freeze before building.');this.require(this.canPlot(x,y)||this.tiles.length===1,'Choose an empty plot beside a developed plot.');this.require(this.reserves>=40,'Infrastructure needs 40 base reserves.');const id='u'+this.nextId++;const e=this.entity(id,'Infrastructure '+id.slice(1).padStart(2,'0'),'utility',x,y);this.post('Infrastructure commissioned · 40 CR',[[id,'equipment',40,0],[id,'capital',0,40],['bank','investment',40,0],['bank','reserves',0,40],['market','reserves',40,0],['market','inventory',0,40]]);this.events.push({type:'build',id});return e;}
 originate(x,y,sponsorId){this.active();this.require(!this.creditFrozen,'Credit frozen: restore liquidity and an 8% capital ratio.');const p=this.entities[sponsorId];this.require(p&&!p.closed,'Select a live subsidiary to sponsor the debt link.');this.require(this.canPlot(x,y),'Choose an adjacent, empty plot.');this.require(Math.abs(p.x-x)+Math.abs(p.y-y)===1,'The new plot must touch its sponsoring tower.');this.require(p.kind==='parent'?this.live('subsidiary').length===0:this.available(p)>=100,'Revalue the sponsor first. Each link pledges 100 equity.');this.require(this.balance('bank').E/(this.risk+100)>=.08,'This loan would take the bank below 8% capital.');const id='s'+this.nextId++;const e=this.entity(id,'Subsidiary '+id.slice(1).padStart(2,'0'),'subsidiary',x,y);e.sponsor=sponsorId;this.post('Loan created · 100 CR',[[id,'deposit',100,0],[id,'debt',0,100],['bank','loans',100,0],['bank','deposits',0,100]]);this.post('Land acquired with credit · 100 CR',[[id,'property',100,0],[id,'deposit',0,100],['market','deposit',100,0],['market','inventory',0,100]]);this.events.push({type:'build',id});return e;}
 revalue(id){this.active();this.require(this.status==='active','Settle the frozen clearing batch before revaluing.');const e=this.entities[id];this.require(e&&!e.closed&&e.kind==='subsidiary','Select a subsidiary to revalue.');this.require(this.balance(e).E>=0,'Resolve insolvency before revaluing.');this.require(e.level<3,'Maximum appraisal reached. Maintain its infrastructure.');const value=this.amount(e,'property');const target=[400,1200,3600][e.level];const increase=target-value;this.post('Projected-capacity revaluation · +'+increase+' CR',[[id,'property',increase,0],[id,'revaluation',0,increase]]);e.level++;this.events.push({type:'rise',id});return e;}
 upgrade(id){this.active();const e=this.entities[id];this.require(e&&!e.closed&&e.kind==='utility','Select infrastructure to upgrade.');this.require(this.status==='active','Resolve settlement first.');this.require(e.upgrades<3,'Infrastructure at maximum capacity.');this.require(this.reserves>=30,'An upgrade needs 30 base reserves.');this.post('Utility expansion · 30 CR',[[id,'equipment',30,0],[id,'capital',0,30],['bank','investment',30,0],['bank','reserves',0,30],['market','reserves',30,0],['market','inventory',0,30]]);e.upgrades++;this.events.push({type:'rise',id});}
 sell(id){this.active();const e=this.entities[id];this.require(e&&!e.closed&&e.kind==='utility','Only infrastructure can be sold for reserves.');const book=this.amount(e,'equipment');const proceeds=Math.floor(book*.75);this.require(this.amount('market','reserves')>=proceeds,'The supplier cannot fund this purchase.');this.post('Infrastructure liquidated · '+proceeds+' CR',[[id,'equipment',0,book],[id,'capital',book,0],['bank','investment',0,book],['bank','reserves',proceeds,0],['bank','retained',book-proceeds,0],['market','reserves',0,proceeds],['market','inventory',proceeds,0]]);e.closed=true;this.events.push({type:'collapse',id});this.refreshProvision();this.check();}
 impair(e,value){const loss=this.amount(e,'property')-value;if(loss<=0)return;const surplus=Math.min(loss,Math.max(0,this.amount(e,'revaluation')));const rows=[[e.id,'property',0,loss]];if(surplus)rows.push([e.id,'revaluation',surplus,0]);if(loss>surplus)rows.push([e.id,'retained',loss-surplus,0]);this.post('Utility failure / '+e.name+' · −'+loss+' CR',rows);this.events.push({type:'fracture',id:e.id});}
 refreshProvision(){const required=this.live('subsidiary').reduce((n,e)=>n+Math.max(0,this.amount(e,'debt')-this.amount(e,'property')),0);const existing=-this.amount('bank','allowance');const delta=required-existing;if(delta>0)this.post('Bank recognizes expected credit loss · '+delta+' CR',[['bank','retained',delta,0],['bank','allowance',0,delta]]);else if(delta<0)this.post('Credit-loss allowance released · '+(-delta)+' CR',[['bank','allowance',-delta,0],['bank','retained',0,-delta]]);}
 absorb(id){this.active();const e=this.entities[id];this.require(e&&!e.closed&&e.kind==='subsidiary'&&this.balance(e).E<0,'Absorption is available for insolvent subsidiaries.');const debt=this.amount(e,'debt');const loss=Math.min(debt,-this.balance(e).E+25);const provision=Math.min(loss,Math.max(0,debt-this.amount(e,'property')));const extra=loss-provision;const rows=[[id,'debt',loss,0],[id,'retained',0,loss],['bank','loans',0,loss]];if(provision)rows.push(['bank','allowance',provision,0]);if(extra)rows.push(['bank','retained',extra,0]);this.post('Parent absorbs subsidiary debt · '+loss+' CR',rows);this.refreshProvision();this.check();}
 isolate(id){this.active();const e=this.entities[id];this.require(e&&!e.closed&&e.kind==='subsidiary'&&this.balance(e).E<0,'Isolation is available for insolvent subsidiaries.');const debt=this.amount(e,'debt'),value=this.amount(e,'property'),loss=debt-value;this.post('Foreclosure / '+e.name,[[id,'debt',debt,0],[id,'property',0,value],[id,'retained',0,loss],['bank','loans',0,debt],['bank','repossessed',value,0],['bank','allowance',loss,0]]);e.closed=true;this.events.push({type:'collapse',id});this.refreshProvision();this.check();}
 collect(){for(const e of this.live('utility')){const n=Math.min(12+e.upgrades*6,this.amount('treasury','reserves'));if(!n)break;this.post('Service receipts / '+e.name+' · '+n+' CR',[[e.id,'deposit',n,0],[e.id,'retained',0,n],['bank','reserves',n,0],['bank','deposits',0,n],['treasury','retained',n,0],['treasury','reserves',0,n]]);this.post('Infrastructure dividend to parent · '+n+' CR',[[e.id,'retained',n,0],[e.id,'deposit',0,n],['bank','deposits',n,0],['bank','retained',0,n]]);}}
 clear(n,advance=true,plan=this.clearingPlan){const {outgoing,incoming}=plan;this.require(n===outgoing-incoming&&this.reserves>=n,'Settlement is not funded.');if(outgoing)this.post('District clearing · '+outgoing+' out / '+incoming+' in / '+n+' net',[['bank','deposits',outgoing,0],['bank','reserves',0,n],['bank','retained',0,incoming],['market','deposit',0,outgoing],['market','outsideDeposit',n,0],['market','retained',incoming,0],['outside','reserves',n,0],['outside','deposits',0,n]]);this.pending=0;this.pendingPlan=null;this.status='active';this.settledDays++;if(advance)this.day++;this.events.push({type:'settle'});this.check(true);}
 stress(){const districts=this.districts();for(const e of this.live('subsidiary'))if(districts[this.district(e)].stress)this.impair(e,Math.floor(this.amount(e,'property')*.65));this.refreshProvision();this.check();}
 endDay(){this.active();if(this.status==='liquidity'){this.day++;this.collect();this.stress();if(this.status==='meltdown')return'Bank capital exhausted. Systemic collapse.';if(this.reserves<this.pending){this.events.push({type:'freeze'});return'A recovery day elapsed. Clearing remains frozen; infrastructure income and utility stress both applied.';}this.clear(this.pending,false);return'Frozen clearing batch settled after a recovery day.';}
 this.require(!this.live('subsidiary').some(e=>this.balance(e).E<0),'Absorb or isolate insolvent subsidiaries before the next day.');const plan=this.clearingPlan,required=plan.net;this.collect();this.stress();if(this.status==='meltdown')return'Bank capital exhausted. Systemic collapse.';
 if(this.reserves<required){this.pending=required;this.pendingPlan=plan;this.status='liquidity';this.events.push({type:'freeze'});return'Liquidity freeze. Clearing needs '+required+' reserves. Your batch remains unpaid.';}this.clear(required,true,plan);return'Settlement complete. '+(this.day%4===0?'Maintenance day: every district loses 2 capacity.':this.day%5===0?'High-clearing day: settlement demand rises 50%.':'All posted books balance.');}
 check(settled=false){if(this.balance('bank').E<=0&&this.status!=='meltdown'){this.status='meltdown';for(const e of this.live('subsidiary'))this.impair(e,0);this.refreshProvision();for(const e of this.live('subsidiary'))this.events.push({type:'collapse',id:e.id});this.events.push({type:'meltdown'});}if(settled&&!this.won&&this.status==='active'&&this.settledDays>=12&&this.footprint>=12&&this.totals.E>=6000&&!this.live('subsidiary').some(e=>this.balance(e).E<0)){this.won=true;this.events.push({type:'win'});}}
 audit(){for(const e of Object.values(this.entities)){const b=this.balance(e);if(b.A!==b.L+b.E)throw Error(e.name+' violates A = L + E');for(const[k,v]of Object.entries(e.accounts)){if(!Number.isSafeInteger(v))throw Error('Unsafe account amount');if(GROUP[k]!=='E'&&k!=='allowance'&&v<0)throw Error('Negative '+k);}}
 const base=Object.values(this.entities).reduce((n,e)=>n+this.amount(e,'reserves'),0);if(this.baseTotal!==undefined&&base!==this.baseTotal)throw Error('Base money not conserved');return true;}
 auditReciprocal(){this.audit();const debt=this.tiles.reduce((n,e)=>n+this.amount(e,'debt'),0);if(this.amount('bank','loans')!==debt)throw Error('Loans do not match borrower debt');const deposits=this.amount('market','deposit')+this.tiles.reduce((n,e)=>n+this.amount(e,'deposit'),0);if(this.amount('bank','deposits')!==deposits)throw Error('Deposits do not match holdings');if(this.amount('market','outsideDeposit')!==this.amount('outside','deposits'))throw Error('Outside deposits mismatch');return true;}
 snapshot(){return{day:this.day,settledDays:this.settledDays,status:this.status,reserves:this.reserves,broadMoney:this.broad,capitalRatio:this.car,combined:this.totals,consolidated:this.consolidated,settlement:this.settlement,clearingPlan:this.clearingPlan,districts:this.districts(),entities:this.tiles.map(e=>({...e,balance:this.balance(e)})),balanced:this.auditReciprocal()};}
}
